pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testRegression_property() public {
        c.setMigrator(address(0x1234567890123456789012345678901234567890));
        address migrator = c.migrator();
        assertTrue(migrator == address(0x1234567890123456789012345678901234567890), "migrator should be set");
    }
}
